// إعداد دائرة التحميل
const loadingCircle = document.createElement('div');
loadingCircle.style.position = 'fixed';
loadingCircle.style.top = '0';
loadingCircle.style.left = '50%';
loadingCircle.style.width = '50px';
loadingCircle.style.height = '50px';
loadingCircle.style.marginLeft = '-25px';
loadingCircle.style.border = '5px solid #f3f3f3';
loadingCircle.style.borderTop = '5px solid #3498db';
loadingCircle.style.borderRadius = '50%';
loadingCircle.style.animation = 'spin 1s linear infinite';
loadingCircle.style.display = 'none';
document.body.appendChild(loadingCircle);

// إضافة CSS لتحريك دائرة التحميل
const style = document.createElement('style');
style.innerHTML = `
@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
`;
document.head.appendChild(style);

// إعداد سحب للتحديث
let pullStartY = null;
let pullMoveY = null;
let dist = 0;
const distThreshold = 70;

window.addEventListener('touchstart', function(e) {
  if (window.scrollY === 0) {
    pullStartY = e.touches[0].screenY;
  }
});

window.addEventListener('touchmove', function(e) {
  if (pullStartY !== null) {
    pullMoveY = e.touches[0].screenY;
    dist = pullMoveY - pullStartY;
    if (dist > 0) {
      e.preventDefault();
      loadingCircle.style.display = 'block';
    }
  }
});

window.addEventListener('touchend', function() {
  if (dist > distThreshold) {
    // قم بتنفيذ عملية التحديث هنا، مثل:
    window.location.reload();
  }
  loadingCircle.style.display = 'none';
  pullStartY = null;
  pullMoveY = null;
  dist = 0;
});
